head.script:
scwin.trigger1_onclick = function() {
	tabControl1.addTab("sub1", {
		"label": "sub1",
		"title": "sub1",
		"openAction": "exist",
		"closable": "true"
	},
	{
		"src": "/sample/common_link/tabControl_spaAuto_windowMaxNum_WESD-1675_(WSQ-5738)_sub.xml",
		"frameMode": "iframe",
		"alwaysDraw": "true"
	});
};

scwin.checkVal1 = function() {
	return (document.getElementById('wq_uuid_1_iframe_0') || document.getElementById('mf_wq_uuid_1_iframe_0')).querySelector('iframe') != null;
};

scwin.checkVal2 = function() {
	return (document.getElementById('wq_uuid_1_iframe_0') || document.getElementById('mf_wq_uuid_1_iframe_0')) === null;
};

scwin.checkVal3 = function() {
	return (document.getElementById('wq_uuid_1_iframe_1') || document.getElementById('mf_wq_uuid_1_iframe_1')).querySelector('iframe') != null;
};
